args.new_string:
get(key) {
  const entry = entries.get(key)
  if (entry === undefined) return undefined
  const now = clock()
  if (now > entry.expiresAt) {
    // TTL passed: treat as a miss and drop the entry
    entries.delete(key)
    return undefined
  }
  entry.lastUsed = now
  // re-insert so the Map order matches recency (last = most recently used)
  entries.delete(key)
  entries.set(key, entry)
  return entry.value
},
set(key, value) {
  const now = clock()
  if (entries.has(key)) {
    // overwrite: re-insert so the key counts as most recently used
    entries.delete(key)
  } else if (entries.size >= capacity) {
    // evict one entry to make room: the least-recently-used one
    // (the front of the recency-ordered Map)
    entries.delete(entries.keys().next().value)
  }
  entries.set(key, { value, expiresAt: now + ttlMs, lastUsed: now })
},

args.old_string:
get(key) {
  const entry = entries.get(key)
  if (entry === undefined) return undefined
  entry.lastUsed = clock()
  return entry.value
},
set(key, value) {
  const now = clock()
  if (entries.size >= capacity && !entries.has(key)) {
    // evict one entry to make room
    const victim = [...entries.entries()].sort((a, b) => b[1].lastUsed - a[1].lastUsed)[0]
    entries.delete(victim[0])
  }
  entries.set(key, { value, expiresAt: now + ttlMs, lastUsed: now })
},

